local gtk=require('retgtk');local app=gtk.application{};local w=gtk.window{title='RetGTK demo',width=640,height=480};local box=gtk.vbox{padding=12,spacing=6};local e=gtk.entry{text='World'};local label=gtk.label{text='Hello'};local b=gtk.button{text='Apply'};b:on('clicked',function() label:set('text','Hello '..e.text) end);box:append(e);box:append(b);box:append(label);w:set_child(box);app:set_window(w);return app
